<?php
require_once(__DIR__ . '/../../config.php'); require_login();
$context=context_system::instance(); require_capability('local/kbacorporate:manageimplementationaudits',$context);
$companyid=required_param('companyid',PARAM_INT); $frameworkid=required_param('frameworkid',PARAM_INT); $query=trim(optional_param('q','',PARAM_TEXT));
$company=\local_kbacorporate\local\access::require_full_company_access($companyid,$USER->id); $framework=$DB->get_record('competency_framework',['id'=>$frameworkid],'*',MUST_EXIST);
$params=['frameworkid'=>$frameworkid,'companyid'=>$companyid]; $where='c.competencyframeworkid=:frameworkid';
if($query!==''){ $where.=' AND ('.$DB->sql_like('c.shortname',':q1',false).' OR '.$DB->sql_like('c.idnumber',':q2',false).')'; $params['q1']='%'.$query.'%'; $params['q2']='%'.$query.'%'; }
$sql="SELECT c.id,c.shortname,c.idnumber,c.parentid,COUNT(DISTINCT CASE WHEN t.companyid IN (0,:companyid) THEN bc.id END) AS mappingcount FROM {competency} c LEFT JOIN {local_kbacorp_bms_comp} bc ON bc.competencyid=c.id LEFT JOIN {local_kbacorp_bms_crit} crit ON crit.id=bc.criterionid LEFT JOIN {local_kbacorp_bms_tool} t ON t.id=crit.toolid WHERE {$where} GROUP BY c.id,c.shortname,c.idnumber,c.parentid ORDER BY c.idnumber ASC,c.shortname ASC";
$records=$DB->get_records_sql($sql,$params);
$PAGE->set_context($context); $PAGE->set_url(new moodle_url('/local/kbacorporate/framework_competencies.php',['companyid'=>$companyid,'frameworkid'=>$frameworkid,'q'=>$query])); $PAGE->set_pagelayout('admin'); $PAGE->set_title(get_string('bmsframeworkcompetencies','local_kbacorporate')); $PAGE->set_heading(format_string($company->name));
echo $OUTPUT->header(); echo local_kbacorporate_implementation_navigation($companyid,'framework'); echo html_writer::div(html_writer::link(new moodle_url('/local/kbacorporate/framework.php',['companyid'=>$companyid,'frameworkid'=>$frameworkid]),'← '.get_string('bmsframeworkmanager','local_kbacorporate')),'kbacorp-backlink'); echo $OUTPUT->heading(get_string('bmsframeworkcompetencies','local_kbacorporate'),2); echo html_writer::tag('p',s((string)$framework->idnumber).' — '.format_string($framework->shortname),['class'=>'kbacorp-pagelead']);
echo html_writer::start_tag('form',['method'=>'get','class'=>'kbacorp-bms-library-filters']); echo html_writer::empty_tag('input',['type'=>'hidden','name'=>'companyid','value'=>$companyid]); echo html_writer::empty_tag('input',['type'=>'hidden','name'=>'frameworkid','value'=>$frameworkid]); echo html_writer::empty_tag('input',['type'=>'search','name'=>'q','value'=>$query,'placeholder'=>get_string('bmsframeworksearchcompetencies','local_kbacorporate'),'class'=>'form-control']); echo html_writer::tag('button',get_string('applyfilter','local_kbacorporate'),['type'=>'submit','class'=>'btn btn-primary']); echo html_writer::end_tag('form');
$table=new html_table(); $table->attributes['class']='generaltable kbacorp-report'; $table->head=[get_string('bmsframeworkcode','local_kbacorporate'),get_string('competencyname','local_kbacorporate'),get_string('bmsframeworkmappedcriteria','local_kbacorporate')];
foreach($records as $record){$url=new moodle_url('/local/kbacorporate/framework_mappings.php',['companyid'=>$companyid,'frameworkid'=>$frameworkid,'competencyid'=>$record->id]); $table->data[]=[s((string)$record->idnumber),format_string($record->shortname),html_writer::link($url,(string)(int)$record->mappingcount)];}
echo html_writer::div(html_writer::table($table),'kbacorp-table-scroll'); echo $OUTPUT->footer();
